cypress_script:
describe('Links API responses', () => {
  it('should handle Created link without navigation', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('a#created').click();
    cy.url().should('eq', 'https://demoqa.com/links');
  });

  it('should handle No Content link without navigation', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('a#no-content').click();
    cy.url().should('eq', 'https://demoqa.com/links');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('Links API responses', () => {
  test('should handle Created link without navigation', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('a#created');
    await expect(page).toHaveURL('https://demoqa.com/links');
  });

  test('should handle No Content link without navigation', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('a#no-content');
    await expect(page).toHaveURL('https://demoqa.com/links');
  });
});
